package com.tracksphere.application.safety;
import com.tracksphere.application.safety.dto.SafetyDtos.*; import com.tracksphere.domain.model.*; import com.tracksphere.domain.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class SafetyService { private final GeofenceRepository geofences; private final SosAlertRepository sos; private final NotificationRepository notifications; private final AuditLogRepository audits; private final UserRepository users; private final SimpMessagingTemplate messages; public GeofenceResponse createGeofence(GeofenceRequest r,UUID actor){Geofence g=geofences.save(new Geofence(r.name(),r.latitude(),r.longitude(),r.radiusMeters()));audit(actor,"GEOFENCE_CREATED",g.getId().toString(),g.getName());return map(g);} public List<GeofenceResponse> geofences(){return geofences.findByActiveTrue().stream().map(this::map).toList();} public SosResponse createSos(SosRequest r,UUID userId){User user=users.findById(userId).orElseThrow();SosAlert alert=sos.save(new SosAlert(user,r.latitude(),r.longitude(),r.message()));SosResponse response=new SosResponse(alert.getId(),user.getFirstName()+" "+user.getLastName(),alert.getStatus(),alert.getCreatedAt());notifications.save(new Notification(user,"SOS alert",response.employee()+" triggered an SOS alert","CRITICAL"));messages.convertAndSend("/topic/alerts",response);audit(userId,"SOS_TRIGGERED",alert.getId().toString(),r.message());return response;} @Transactional(readOnly=true) public List<SosResponse> sos(){return sos.findTop100ByOrderByCreatedAtDesc().stream().map(a->new SosResponse(a.getId(),a.getUser().getFirstName()+" "+a.getUser().getLastName(),a.getStatus(),a.getCreatedAt())).toList();} @Transactional(readOnly=true) public List<NotificationResponse> notifications(UUID userId){return notifications.findTop50ByUserIdOrderByCreatedAtDesc(userId).stream().map(n->new NotificationResponse(n.getId(),n.getTitle(),n.getMessage(),n.getSeverity(),n.getCreatedAt(),n.getReadAt())).toList();}@Transactional(readOnly=true) public List<AuditResponse> audit(){return audits.findTop100ByOrderByCreatedAtDesc().stream().map(a->new AuditResponse(a.getId(),a.getActorId(),a.getAction(),a.getTarget(),a.getDetails(),a.getCreatedAt())).toList();} public void audit(UUID actor,String action,String target,String details){audits.save(new AuditLog(actor,action,target,details));} private GeofenceResponse map(Geofence g){return new GeofenceResponse(g.getId(),g.getName(),g.getLatitude(),g.getLongitude(),g.getRadiusMeters(),g.isActive());} }
